java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
try (java.io.InputStream is = new java.io.FileInputStream(grid_png)) {
    net.coobird.thumbnailator.ThumbnailParameter param = new net.coobird.thumbnailator.ThumbnailParameter(
            new java.awt.Dimension(50, 50),
            null,
            true,
            "png",
            net.coobird.thumbnailator.ThumbnailParameter.DEFAULT_FORMAT_TYPE,
            net.coobird.thumbnailator.ThumbnailParameter.DEFAULT_QUALITY,
            java.awt.image.BufferedImage.TYPE_INT_ARGB,
            null,
            net.coobird.thumbnailator.resizers.Resizers.PROGRESSIVE,
            true,
            true
    );

    net.coobird.thumbnailator.tasks.StreamThumbnailTask task = new net.coobird.thumbnailator.tasks.StreamThumbnailTask(param, is, baos);

    java.awt.image.BufferedImage img = task.read();
    assert img != null : "Read image should not be null";
    assert img.getWidth() > 0 && img.getHeight() > 0 : "Image should have valid dimensions";

    task.write(img);
}

byte[] resultBytes = baos.toByteArray();
assert resultBytes.length > 0 : "Output stream should contain data";

java.io.ByteArrayInputStream bais = new java.io.ByteArrayInputStream(resultBytes);
java.awt.image.BufferedImage resultImg = javax.imageio.ImageIO.read(bais);
assert resultImg != null : "Resulting image should be readable";
assert resultImg.getWidth() > 0 : "Resulting image width should be positive";

System.out.println("__CHECK__ StreamThumbnailTask " + resultImg.getWidth() + "x" + resultImg.getHeight() + " bytes:" + resultBytes.length);
